const url = $('Page URL Form').first().json['Page URL'];
const html = String(await this.helpers.httpRequest({ url }));
const pick = re => (html.match(re) || [, ''])[1].replace(/\s+/g, ' ').trim();
return [{ json: { url, title: pick(/<title>([^<]+)<\/title>/i), description: pick(/<meta name="description" content="([^"]+)"/i),
  images: (html.match(/<img(?![^>]*\balt=)[^>]*src="([^"]+)"/gi) || []).slice(0, 10),
  text: html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 6000) } }];

const o = JSON.parse($json.candidates[0].content.parts[0].text), pg = $('Fetch Page').first().json;
const draft = 'SEO title: ' + o.seo_title + '

Meta description: ' + o.meta_description + '

Alt text:
' + (o.alt_text || []).map(a => '- ' + a.src + ': ' + a.alt).join('
') + '

Internal links:
' + (o.internal_links || []).map(l => '- ' + l.anchor_text + ' to ' + l.target_url).join('
');
return [{ json: { ID: 'q' + Date.now(), Created: new Date().toISOString(), Workflow: 'Metadata and internal links', Kind: 'metadata', Target: pg.url, Subject: 'Metadata For ' + pg.title, Draft: draft, Status: 'for review' } }];
